sci:arg.sci:value:
$( document ).ready(function() {
	// initialse tooltips
	$('[data-toggle="tooltip"]').tooltip({
		placement: 'bottom',
	});

	// initialse popovers
	$('[data-toggle="popover"]').popover({
		trigger: 'hover',
		placement: 'right',
		html: true,
	});

	// attach the date pickers to the UI elements
	$(".datePickerTextBox").datepicker({
		format: "dd/mm/yyyy",
		autoclose: true,
		todayHighlight: true,
		todayBtn: true
	});
})

